201	// stripANSI removes escape sequences so column positions can be compared.
202	func stripANSI(s string) string {
203		var b strings.Builder
204		inEscape := false
205		for _, r := range s {
206			switch {
207			case r == '\x1b':
208				inEscape = true
209			case inEscape && r == 'm':
210				inEscape = false
211			case !inEscape:
212				b.WriteRune(r)
213			}
214		}
215		return b.String()
216	}

