210	// FetchOCIStats returns OCI resource counts and disk usage via docker system df
211	func FetchOCIStats() OCIStats {
212		stats := OCIStats{}
213	
214		if _, err := exec.LookPath("docker"); err != nil {
215			return stats
216		}
217	
218		cmd := exec.Command("docker", "system", "df", "--format", "{{.Type}}\t{{.TotalCount}}\t{{.Size}}")
219		output, err := cmd.Output()
