223	
224		stats.Available = true
225	
226		for line := range strings.SplitSeq(strings.TrimSpace(string(output)), "\n") {
227			if line == "" {
228				continue
229			}
230			parts := strings.SplitN(line, "\t", 3)
231			if len(parts) < 3 {
232				continue
233			}
234			typeName := parts[0]
235			count, _ := strconv.Atoi(parts[1])
236			size := parts[2]
237	
238			switch typeName {
239			case "Images":
240				stats.ImagesCount = count
241				stats.ImagesSize = size
242			case "Containers":
243				stats.ContainersCount = count
244				stats.ContainersSize = size
