254	// Image represents a Docker image with its metadata
255	type Image struct {
256		ID         string
257		Repository string
258		Tag        string
259		Size       int64 // Content size (virtual size) in bytes
260		UniqueSize int64 // Disk usage (unique layers) in bytes
261		Containers int
262		CreatedAt  string
263	}
264	
265	// Name returns "repository:tag", omitting the tag suffix when tag is "<none>".
266	func (img Image) Name() string {
267		if img.Tag == "" || img.Tag == "<none>" {
268			return img.Repository
269		}
270		return img.Repository + ":" + img.Tag
271	}
272	
273	// ScanTarget returns the best identifier to pass to Trivy for a local scan.
274	// When an image has no tag, the short ID is used so Trivy resolves it locally
275	// instead of trying to pull "repository:latest" from a registry.
276	func (img Image) ScanTarget() string {
277		if img.Tag == "" || img.Tag == "<none>" {
278			return img.ID
279		}
280		return img.Name()
281	}
